public class DebuggerRegionsPlugin : AbstractDebuggerPlugin {
	protected DebuggerRegionsProvider provider;

	public DebuggerRegionsPlugin(PluginTool tool) : base(tool)
    {
	}

	/* @Override */
	protected void init() {
		provider = new DebuggerRegionsProvider(this);
		base.init();
	}

	/* @Override */
	protected void dispose() {
		tool.removeComponentProvider(provider);
		provider.dispose();
		base.dispose();
	}

	/* @Override */
	public void processEvent(PluginEvent @event) {
		base.processEvent(@event);
		if (@event is ProgramActivatedPluginEvent ev) {
			provider.setProgram(ev.getActiveProgram());
		}
		else if (@event is ProgramLocationPluginEvent ev) {
			provider.setLocation(ev.getLocation());
		}
		else if (@event is ProgramClosedPluginEvent ev) {
			provider.programClosed(ev.getProgram());
		}
		else if (@event is TraceActivatedPluginEvent ev) {
			provider.coordinatesActivated(ev.getActiveCoordinates());
		}
	}
}
